import asyncio,json
from pathlib import Path
OUTPUT = Path("/tmp/browser/orbit-improvements")
OUTPUT.mkdir(parents=True, exist_ok=True)
from playwright.async_api import async_playwright
async def main():
 async with async_playwright() as p:
  b=await p.chromium.launch(headless=True); c=await b.new_context(viewport={'width':1280,'height':1800}); owner=await c.new_page(); errors=[]; owner.on('pageerror',lambda e:errors.append(str(e)))
  await owner.goto('http://localhost:8080/create',wait_until='networkidle'); await owner.get_by_placeholder('Your name').fill('Focus Owner')
  for _ in range(3): await owner.get_by_role('button',name='Continue',exact=True).click()
  await owner.get_by_placeholder('e.g. The Launchpad').fill('Orbit Focus Review'); await owner.get_by_role('button',name='Enter the house',exact=True).click(); await owner.wait_for_url('**/house/**'); await owner.wait_for_timeout(3500)
  code=await owner.get_by_label('House code').inner_text(); h=owner.url.rsplit('/',1)[-1]
  c2=await b.new_context(viewport={'width':1280,'height':1800}); guest=await c2.new_page(); guest.on('pageerror',lambda e:errors.append(str(e)))
  await guest.goto('http://localhost:8080/join/'+code,wait_until='networkidle'); await guest.get_by_placeholder('Your name').fill('Focus Guest'); await guest.get_by_role('button',name='Enter the house',exact=True).click(); await guest.wait_for_url('**/house/**'); await guest.wait_for_timeout(3500)
  async def rpc(pg,action,payload={}):
   return await pg.evaluate("""async ([h,a,p])=>{const {supabase}=await import('/src/integrations/supabase/client.ts');const {data,error}=await supabase.rpc('orbit_experience',{_house:h,_action:a,_payload:p});return {data,error:error?.message}}""",[h,action,payload])
  async def snap(pg):
   r=await rpc(pg,'snapshot'); assert not r.get('error'),r; return r['data']
  async def walk(pg,x,y):
   svg=pg.locator('main svg').first; pt=await svg.evaluate('(e,p)=>{const q=e.createSVGPoint();q.x=p.x;q.y=p.y;const r=q.matrixTransform(e.getScreenCTM());return {x:r.x,y:r.y}}',{'x':x,'y':y}); await pg.mouse.click(pt['x'],pt['y']); await pg.wait_for_timeout(8000)
  ownerid=await owner.evaluate("async()=>{const {supabase}=await import('/src/integrations/supabase/client.ts');return (await supabase.auth.getUser()).data.user.id}"); first=await snap(owner); assert first['visits']; start=next(v['started_at'] for v in first['visits'] if v['user_id']==ownerid); await owner.reload(wait_until='networkidle'); await owner.wait_for_timeout(3500); assert next(v['started_at'] for v in (await snap(owner))['visits'] if v['user_id']==ownerid)==start
  print('Refresh preserves visit')
  await walk(owner,300,500); await walk(guest,400,500)
  before=await guest.evaluate("async h=>{const {supabase}=await import('/src/integrations/supabase/client.ts');const uid=(await supabase.auth.getUser()).data.user.id;return (await supabase.from('house_activity').select('motion_id').eq('house_id',h).eq('user_id',uid).single()).data.motion_id}",h)
  await guest.locator('main svg').get_by_role('button',name='About Focus Owner').click(force=True); await guest.get_by_role('dialog').wait_for(); assert 'In this house for' in await guest.get_by_role('dialog').inner_text(); await guest.get_by_role('button',name='Wave',exact=True).click(); await owner.get_by_text('Focus Guest waved hello',exact=True).wait_for(timeout=8000); await guest.get_by_role('button',name='Close',exact=True).click(); assert before==await guest.evaluate("async h=>{const {supabase}=await import('/src/integrations/supabase/client.ts');const uid=(await supabase.auth.getUser()).data.user.id;return (await supabase.from('house_activity').select('motion_id').eq('house_id',h).eq('user_id',uid).single()).data.motion_id}",h); print('Profile no movement; wave delivered')
  await owner.get_by_role('button',name='Focus',exact=True).click(); await owner.get_by_label('Shared room session').check(); await owner.get_by_role('button',name='Start focus',exact=True).click(); await owner.wait_for_timeout(1500); a=await snap(owner); t=next(t for t in a['timers'] if t['room_key']=='lounge'); sid=t['id']
  assert not (await rpc(guest,'join',{'id':sid})).get('error'); assert (await rpc(guest,'pause',{'id':sid})).get('error'); assert not (await rpc(owner,'pause',{'id':sid})).get('error'); paused=(await snap(guest))['timers'][0]; assert paused['state']=='paused'; assert not (await rpc(owner,'resume',{'id':sid})).get('error'); assert (await rpc(guest,'leave_focus',{'id':sid})).get('error') is None; assert next(t for t in (await snap(owner))['timers'] if t['id']==sid)['state']=='running'; assert not (await rpc(guest,'join',{'id':sid})).get('error'); print('Shared countdown, host authorization, independent leave')
  await owner.get_by_role('dialog').screenshot(path='/tmp/browser/orbit-improvements/timer.png'); await owner.get_by_role('button',name='Close',exact=True).click()
  await guest.get_by_role('button',name='Chat',exact=True).click(); await guest.get_by_label('Room message').fill('Hello from the lounge'); await guest.get_by_role('button',name='Send',exact=True).click(); await guest.get_by_text('Hello from the lounge',exact=True).wait_for(); await owner.get_by_role('button',name='Chat',exact=False).click(); await owner.get_by_text('Hello from the lounge',exact=True).wait_for(timeout=8000); print('Persisted room chat reads on both identities')
  await owner.get_by_role('button',name='Close',exact=True).click(); await guest.get_by_role('button',name='Close',exact=True).click()
  uid=await owner.evaluate("async()=>{const {supabase}=await import('/src/integrations/supabase/client.ts');return (await supabase.auth.getUser()).data.user.id}")
  await owner.get_by_label('Availability').select_option('dnd'); await owner.wait_for_timeout(1500); assert (await rpc(guest,'wave',{'target':uid})).get('error'); assert (await rpc(guest,'wave',{'target':uid})).get('error'); print('DND denies social interruptions')
  await walk(guest,900,500); assert not (await snap(guest))['messages']; assert (await rpc(guest,'join',{'id':sid})).get('error'); print('Leaving clears room chat and denies timer join')
  screen=await guest.evaluate("""async h=>{const {supabase}=await import('/src/integrations/supabase/client.ts');const {data,error}=await supabase.rpc('orbit_screen',{_house:h,_action:'reserve',_room:'kitchen',_share:true});return {data,error:error?.message}}""",h); assert not screen.get('error'),screen; await walk(guest,400,500)
  denied=await guest.evaluate("""async ([h,id])=>{const {supabase}=await import('/src/integrations/supabase/client.ts');return !!(await supabase.rpc('orbit_screen',{_house:h,_action:'check',_lease:id})).error}""",[h,screen['data']['id']]); assert denied; print('Screen lease revoked on movement')
  assert not (await rpc(owner,'decorate',{'name':'Quiet Nest','palette':'sage','decor':'books'})).get('error'); assert any(r['name']=='Quiet Nest' for r in (await snap(guest))['settings']); print('Owner decor persists and synchronizes'); await guest.set_viewport_size({'width':390,'height':844}); await guest.get_by_role('button',name='People',exact=True).click(); await guest.get_by_role('dialog').screenshot(path='/tmp/browser/orbit-improvements/phone-profile-list.png'); assert not await guest.evaluate('document.documentElement.scrollWidth>innerWidth'); await guest.get_by_role('button',name='Close',exact=True).click(); await guest.wait_for_timeout(700); await guest.screenshot(path='/tmp/browser/orbit-improvements/phone.png')
  guestid=await guest.evaluate("async()=>{const {supabase}=await import('/src/integrations/supabase/client.ts');return (await supabase.auth.getUser()).data.user.id}"); gueststart=next(x['started_at'] for x in (await snap(guest))['visits'] if x['user_id']==guestid); await guest.get_by_role('button',name='Leave house',exact=True).click(); await guest.goto('http://localhost:8080/enter',wait_until='networkidle'); await guest.get_by_text('Orbit Focus Review',exact=True).wait_for(); await guest.get_by_role('button',name='Re-enter',exact=True).click(); await guest.wait_for_url('**/house/**'); await guest.wait_for_timeout(3500); v=await snap(guest); assert next(x['started_at'] for x in v['visits'] if x['user_id']==guestid)!=gueststart; print('Recent house re-entry; explicit leave starts new visit')
  print('Page errors',errors); assert not errors; await b.close()
asyncio.run(main())
